import Foundation

public enum MapAppearance: String, Sendable {
    case day, night

    /// Bundled style generated by Tools/mapstyle/build_styles.py.
    public var styleURL: URL {
        guard let url = Bundle.module.url(forResource: "atlas-\(rawValue)", withExtension: "json", subdirectory: "Styles") else {
            preconditionFailure("Missing bundled map style atlas-\(rawValue).json")
        }
        return url
    }
}

/// Style layer ids the app changes at runtime; must match Tools/mapstyle/build_styles.py.
enum MapLayerID {
    static let buildings3D = "building-3d"
}
